// @spec: COR
import fs from 'node:fs';
const c = JSON.parse(fs.readFileSync('config/runtime.json', 'utf8'));
if (!Number.isFinite(c.maxWaitMs) || c.maxWaitMs < 0) { console.error('RECOVERABLE_TECHNICAL: config/runtime.json maxWaitMs must be finite and nonnegative'); process.exit(2); }

// @file: Approved normal and invalid-input scenarios.
// @spec: COR
// @consumers: N/A
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { boundedDelay } from './delay.ts';
test('[COR-REQ-1] public behavior', () => { assert.equal(boundedDelay(200, 50), 50); });
test('[COR-REQ-2] invalid input', () => { assert.throws(() => boundedDelay(-1, 50), RangeError); });

// @file: Pure boundedDelay implementation.
// @spec: COR
// @consumers: src/delay.test.ts

/** @purpose Cap a requested delay at an upper bound without waiting. | @param value Requested milliseconds. | @param limit Upper bound milliseconds. | @throws RangeError When either argument is not a finite nonnegative number. | @returns The smaller of the two nonnegative millisecond values, including zero. */
export function boundedDelay(value: number, limit: number): number {
  if (!Number.isFinite(value) || !Number.isFinite(limit) || value < 0 || limit < 0) {
    throw new RangeError(`[boundedDelay] invalid delay: value=${String(value)} limit=${String(limit)}`);
  }
  return Math.min(value, limit);
}
